<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { ipcRenderer } from 'electron';

type Attachment = { name: string; path: string; size: number };
type State = { logging: { sources: Record<string, boolean>; autoEnabledUntil?: string; lastErrorAt?: string }; feedback: any[]; tickets: any[]; remote: { status: string; requestedAt?: string; approvedAt?: string; endedAt?: string } };
const sections = ['home', 'logs', 'feedback', 'tickets', 'remote'] as const;
const section = ref<string>('home'); const state = ref<State | null>(null); const logs = ref<any[]>([]); const busy = ref(false); const notice = ref('');
const feedbackBody = ref(''); const feedbackFiles = ref<Attachment[]>([]); const subject = ref(''); const ticketBody = ref(''); const ticketFiles = ref<Attachment[]>([]);
const sourceLabels: Record<string, string> = { desktop: 'Desktop app', runtime: 'Sulla runtime', containers: 'Containers', ai: 'AI connections' };
const remoteCopy = computed(() => ({ idle: ['Remote support is off', 'Request help when setup or Sulla is not working.'], waiting: ['Waiting for Sulla support', 'Your request is saved. You can close this window or restart Sulla.'], approval: ['One-time approval needed', 'Jonathon from Sulla is ready to connect. Review the limits before approving.'], connected: ['Support is connected', 'Jonathon can diagnose only inside the Sulla runtime VM.'], ended: ['Remote support ended', 'Access has been removed. Nothing remains connected.'] } as any)[state.value?.remote.status || 'idle']);
function navigate(value: string) { section.value = sections.includes(value as any) ? value : 'home'; if (section.value === 'logs') void loadLogs() }
function fromHash() { navigate(location.hash.slice(1).split('?')[0]) }
async function refresh() { state.value = await ipcRenderer.invoke('support:state') }
async function loadLogs() { logs.value = await ipcRenderer.invoke('support:logs') }
async function setSource(source: string, enabled: boolean) { state.value = await ipcRenderer.invoke('support:set-source', source, enabled); await loadLogs() }
async function choose(target: typeof feedbackFiles) { target.value = await ipcRenderer.invoke('support:choose-files') }
async function submitFeedback() { busy.value = true; try { state.value = await ipcRenderer.invoke('support:add-feedback', { body: feedbackBody.value, attachments: feedbackFiles.value }); feedbackBody.value = ''; feedbackFiles.value = []; notice.value = 'Feedback saved and ready to send when Cloud support is connected.' } finally { busy.value = false } }
async function createTicket() { busy.value = true; try { state.value = await ipcRenderer.invoke('support:create-ticket', { subject: subject.value, body: ticketBody.value, attachments: ticketFiles.value }); subject.value = ''; ticketBody.value = ''; ticketFiles.value = []; notice.value = 'Ticket created locally.' } finally { busy.value = false } }
async function remote(action: string) { state.value = await ipcRenderer.invoke('support:remote', action) }
let timer: any; onMounted(async() => { window.addEventListener('hashchange', fromHash); ipcRenderer.on('support:navigate', (_event, value) => navigate(value)); fromHash(); await refresh(); timer = setInterval(() => { if (section.value === 'logs') void loadLogs() }, 3000) }); onBeforeUnmount(() => { clearInterval(timer); window.removeEventListener('hashchange', fromHash) });
</script>
<template><div class="shell"><aside><div class="brand">Sulla <b>Support</b></div><a v-for="s in sections" :key="s" :href="`#${s}`" :class="{on:section===s}">{{ {home:'Support Center',logs:'Logs',feedback:'Send feedback',tickets:'Tickets',remote:'Remote support'}[s] }}</a><div class="privacy">🔒 Support never sees your Files, passwords or chats.</div></aside><main v-if="state"><div v-if="notice" class="notice">{{ notice }} <button @click="notice=''">×</button></div>
<section v-if="section==='home'"><h1>Support Center</h1><p class="lead">Get help with Sulla Desktop. Everything here works even if setup didn't finish.</p><div class="tiles"><a href="#logs"><b>Logs</b><span>See what Sulla is doing and choose which sources are recorded.</span><small v-if="state.logging.lastErrorAt">On automatically after an error</small></a><a href="#feedback"><b>Send feedback</b><span>Share an idea or tell us what could work better.</span></a><a href="#tickets"><b>Tickets</b><span>Create a support ticket and follow its thread.</span><small>{{state.tickets.length}} local ticket(s)</small></a><a href="#remote"><b>Remote support</b><span>Let support diagnose your Sulla runtime with your approval.</span><small>{{state.remote.status}}</small></a></div></section>
<section v-else-if="section==='logs'"><h1>Logs</h1><p class="lead">Live local logs. Logging turns on for 24 hours whenever an error happens.</p><div class="alert">Logs never include file contents, passwords, chats or API keys. Common credential fields are redacted in this viewer.</div><div class="sources"><label v-for="(label,key) in sourceLabels" :key="key"><span><b>{{label}}</b></span><input type="checkbox" :checked="state.logging.sources[key]" @change="setSource(key,($event.target as HTMLInputElement).checked)"></label></div><button @click="loadLogs">Refresh</button><div class="terminal"><template v-if="logs.length"><div v-for="log in logs" :key="log.source+log.name"><strong>[{{log.source}} / {{log.name}}]</strong>\n{{log.text}}</div></template><span v-else>No log entries found for the enabled sources.</span></div></section>
<section v-else-if="section==='feedback'"><h1>Send feedback</h1><p class="lead">Tell us what happened or what you'd like Sulla to do.</p><textarea v-model="feedbackBody" maxlength="10000" placeholder="Your feedback"></textarea><div class="attach"><button @click="choose(feedbackFiles)">Attach files</button><span>{{feedbackFiles.map(f=>f.name).join(', ') || 'No files selected'}}</span></div><button class="primary" :disabled="busy||!feedbackBody.trim()" @click="submitFeedback">Save feedback</button><p class="hint">This first Desktop slice keeps feedback locally; Cloud delivery follows in the support backend slice.</p></section>
<section v-else-if="section==='tickets'"><h1>Tickets</h1><div class="grid"><div><div v-if="!state.tickets.length" class="empty">No tickets yet.</div><article v-for="ticket in state.tickets" :key="ticket.id"><b>{{ticket.subject}}</b><small>{{ticket.id}} · {{new Date(ticket.createdAt).toLocaleString()}}</small><p>{{ticket.body}}</p><div v-for="reply in ticket.replies" :key="reply.id" class="reply">{{reply.body}}</div></article></div><form @submit.prevent="createTicket"><h2>Create ticket</h2><input v-model="subject" maxlength="160" placeholder="What do you need help with?"><textarea v-model="ticketBody" maxlength="10000" placeholder="Describe the problem"></textarea><button type="button" @click="choose(ticketFiles)">Attach files</button><span class="files">{{ticketFiles.map(f=>f.name).join(', ')}}</span><button class="primary" :disabled="busy||!subject.trim()||!ticketBody.trim()">Create ticket</button></form></div></section>
<section v-else><h1>Remote support</h1><p class="lead">A Sulla engineer can diagnose the Sulla runtime. Nothing runs on your Mac.</p><div class="remote"><h2>{{remoteCopy[0]}}</h2><p>{{remoteCopy[1]}}</p><div class="scope"><div><b>Support can</b><ul><li>Read Sulla logs</li><li>Diagnose the runtime VM</li><li>Check containers</li></ul></div><div><b>Support can't</b><ul><li>Run anything on your Mac</li><li>Open Files or chats</li><li>See passwords or the vault</li></ul></div></div><button v-if="state.remote.status==='idle'||state.remote.status==='ended'" class="primary" @click="remote('request')">Request remote support</button><button v-else-if="state.remote.status==='waiting'" class="danger" @click="remote('end')">Cancel request</button><template v-else-if="state.remote.status==='approval'"><div class="approval"><b>Jonathon from Sulla wants to connect</b><p>This one approval persists across restarts until you end it.</p></div><button class="primary" @click="remote('approve')">Approve connection</button><button @click="remote('end')">Decline</button></template><button v-else-if="state.remote.status==='connected'" class="danger" @click="remote('end')">End support access</button></div></section></main></div></template>
<style scoped>
:global(*){box-sizing:border-box}:global(body){margin:0;font:14px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#1c2736;background:#f4f7fa}.shell{min-height:100vh;display:grid;grid-template-columns:220px 1fr}aside{padding:24px 14px;background:#fff;border-right:1px solid #dbe2e9;display:flex;flex-direction:column;gap:5px}.brand{font-size:18px;padding:0 10px 20px;color:#397f9e}aside a{padding:10px 12px;border-radius:8px;color:#566576;text-decoration:none;text-transform:capitalize}aside a.on{background:#e8f2f6;color:#286b88;font-weight:600}.privacy{margin-top:auto;padding:12px;font-size:12px;color:#738192;background:#f5f8fa;border-radius:9px}main{padding:38px 44px;max-width:1100px;width:100%}h1{font-size:28px;margin:0 0 6px}h2{font-size:17px}.lead{color:#667587;margin:0 0 28px}.tiles{display:grid;grid-template-columns:1fr 1fr;gap:14px}.tiles a,article,form,.remote{display:flex;flex-direction:column;gap:9px;padding:20px;border:1px solid #d8e0e8;border-radius:12px;background:#fff;color:inherit;text-decoration:none}.tiles a{min-height:145px}.tiles b{font-size:17px}.tiles span,.tiles small,small,.hint{color:#748293}.alert,.notice{padding:13px 15px;background:#e7f2f7;border:1px solid #bad7e3;border-radius:9px;margin-bottom:16px}.notice button{float:right;border:0;background:transparent}.sources{display:flex;gap:10px;margin-bottom:14px}.sources label{display:flex;align-items:center;justify-content:space-between;gap:18px;background:#fff;border:1px solid #d8e0e8;border-radius:9px;padding:10px 12px;min-width:150px}.terminal{margin-top:12px;padding:16px;height:370px;overflow:auto;white-space:pre-wrap;background:#0d1520;color:#cbd7e4;border-radius:10px;font:12px/1.55 ui-monospace,monospace}.terminal strong{color:#70b5d3}.grid{display:grid;grid-template-columns:1.25fr 1fr;gap:18px}.grid>div{display:flex;flex-direction:column;gap:12px}.empty{padding:50px;text-align:center;color:#748293;background:#fff;border:1px dashed #cbd5df;border-radius:10px}textarea,input{width:100%;border:1px solid #cbd6e0;border-radius:8px;padding:11px;font:inherit;background:#fff}textarea{height:170px;resize:vertical}.attach{display:flex;align-items:center;gap:12px;margin:10px 0}.attach span,.files{font-size:12px;color:#748293}button{border:1px solid #bdc9d4;background:#fff;padding:9px 14px;border-radius:8px;cursor:pointer}.primary{background:#397f9e;border-color:#397f9e;color:#fff}.danger{background:#fff1f1;color:#b02c2c;border-color:#efc1c1}.scope{display:grid;grid-template-columns:1fr 1fr;gap:12px}.scope>div{padding:14px;background:#f6f8fa;border-radius:9px}.scope ul{padding-left:19px;color:#627183;line-height:1.8}.remote{max-width:720px}.remote button{align-self:flex-start}.approval{padding:14px;background:#e8f2f6;border-radius:9px}
</style>
